// GENERIERT von kommunikation/n8n/bauen-antwort.mjs – nicht von Hand ändern.
// KOM: WhatsApp Antwort (Workflow B). Wird von Workflow A pro neuer Kundennachricht aufgerufen (nicht wartend).
// Wege: Kunde (Begrüßung oder KI-Vertriebsassistent), Team (bestehender Portal-Assistent mit Firmenwissen, rollengerecht),
// Befehl (/kunde, /team für Teammitglieder), still (Mensch hat übernommen, Testmodus, neuere Nachricht folgt).
import { workflow, node, trigger, ifElse, switchCase, expr } from '@n8n/workflow-sdk';

// Gemeinsame Logik aus kommunikation/lib/antwort.js (getestet), in jedem Code-Knoten vorangestellt
const LIB = "// Kommunikation: Logik des WhatsApp-Assistenten (Workflow B). Läuft im n8n-Code-Knoten (eingebettet von bauen.mjs) und in Node (Tests).\n// Kein Netzwerk, kein require. Die Knoten rufen nur diese Funktionen auf.\n\nconst BUCHUNG_KARSTEN = 'https://api.leadconnectorhq.com/widget/bookings/beratung-momentum-ki-akademie';\nconst DATENSCHUTZ = 'momentum-ki-akademie.de/datenschutz';\n\n// Erste Antwort, Endfassung nach Textprüfung (KOM_Erstnachricht_Entwurf.md, freigegeben von Timo am 13.11.2026)\nconst DATENSCHUTZ_ZEILE = 'Datenschutz: ' + DATENSCHUTZ;\n\n/** Fall A: erste Nachricht ist nur ein Gruß, kein Anliegen. */\nconst BEGRUESSUNG =\n  'Hi 👋 Ich bin der KI-Assistent der Momentum KI Akademie und von Hermetik Marketing. Ich beantworte dir gern Fragen zu KI im Betrieb und zur Mitarbeiterförderung. Worum geht\\'s?\\n\\n' +\n  DATENSCHUTZ_ZEILE;\n\n/** Fall C: WhatsApp-Knopf der Webseite mit neutralem vorbelegtem Text (ohne Thema). */\nconst BEGRUESSUNG_WEBSEITE =\n  'Hi, ich bin der KI-Assistent der Momentum KI Akademie und von Hermetik Marketing. Geht es dir um geförderte Schulung fürs Team oder um ein KI-System für deinen Betrieb?\\n\\n' +\n  DATENSCHUTZ_ZEILE;\n\n/** Knöpfe der Begrüßung (je höchstens 20 Zeichen). Alte Knöpfe aus laufenden Gesprächen: „Umsetzung“, „Mitarbeiterschulung“. */\nconst KNOEPFE = ['KI-System im Betrieb', 'Geförderte Schulung'];\n\n/**\n * Neutrale Vorbelegungstexte von WhatsApp-Knöpfen auf Webseiten (Fall C), klein geschrieben, ohne Satzzeichen.\n * Stand 13.11.2026 auf momentum-ki-akademie.de: Beide Knöpfe mit Text nennen schon ein Thema\n * („… interessiere mich für die KI-Weiterbildung“, „… möchte direkt mit Timo Kontakt aufnehmen“) und laufen deshalb als Fall B.\n * Neue neutrale Knopf-Texte hier ergänzen.\n */\nconst NEUTRALE_VORBELEGUNGEN = [\n  'hallo ich komme von der website',\n  'hallo ich komme von der webseite',\n  'hallo ich komme von eurer website',\n  'hallo ich komme von eurer webseite',\n  'hallo ich komme von ihrer website',\n  'hallo ich komme von ihrer webseite',\n  'ich komme von der website',\n  'ich komme von der webseite'\n];\n\nconst ohneZeichen = text => String(text || '').toLowerCase()\n  .replace(/[\\p{Extended_Pictographic}\\u{1F3FB}-\\u{1F3FF}‍️]/gu, ' ')\n  .replace(/[!.?,;:…\\-–—()\"'“”„*_~]+/g, ' ')\n  .replace(/\\s+/g, ' ').trim();\n\nconst GRUSS = '(hi+|hii+|hallo+|hallöchen|halli hallo|hello|hey+|huhu|moin( moin)?|servus|grüß gott|grüss gott|gruess gott|grüezi|grüß dich|grüss dich|guten (tag|morgen|abend)|gute?n? morgen|tach|tag|na|yo|salut|ciao|test( \\\\d+)?|info|infos)';\nconst GRUSS_RE = new RegExp('^' + GRUSS + '( ' + GRUSS + ')*( (zusammen|leute|team|ihr|timo|karsten))?$');\n\n/** Nur ein Gruß ohne Anliegen (auch nur Emojis)? Dann Fall A: feste Begrüßung mit den zwei Knöpfen. */\nfunction istKurzgruss(text) {\n  const t = ohneZeichen(text);\n  if (t.length === 0) return true;\n  if (t.length > 40) return false;\n  return GRUSS_RE.test(t);\n}\n\n/** Neutraler vorbelegter Text vom WhatsApp-Knopf einer Webseite (Fall C)? */\nfunction istNeutraleVorbelegung(text) {\n  return NEUTRALE_VORBELEGUNGEN.includes(ohneZeichen(text));\n}\n\n/**\n * Welche erste Antwort? '' = kein Erstkontakt (normales Gespräch),\n * 'A' = nur Gruß → feste Begrüßung, 'C' = neutraler Webseiten-Text → fester Text, 'B' = Anliegen → KI mit Regel „Erste Antwort“.\n * Sprachnachrichten, Bilder, Dokumente gelten als Anliegen (B).\n */\nfunction erstkontaktFall(eingang, nachricht) {\n  if (!(eingang && eingang.erstkontakt)) return '';\n  const n = nachricht || {};\n  const typ = n.typ || 'text';\n  const nurText = ['text', 'interactive', 'button', 'reaction', 'sticker'].includes(typ);\n  if (nurText && istKurzgruss(n.text)) return 'A';\n  if (nurText && istNeutraleVorbelegung(n.text)) return 'C';\n  return 'B';\n}\n\n/** Datenschutz-Zeile als eigene letzte Zeile anhängen, falls sie fehlt (nie doppelt). */\nfunction mitDatenschutz(text) {\n  const t = String(text || '').trimEnd();\n  if (t.toLowerCase().includes(DATENSCHUTZ)) return t;\n  return t + '\\n\\n' + DATENSCHUTZ_ZEILE;\n}\n\n/** Text, den die KI für eine Nachricht sieht (auch bei Medien ohne Text). */\nfunction textFuerKi(n) {\n  const t = String((n && n.text) || '').trim();\n  const typ = (n && n.typ) || 'text';\n  if (typ === 'text' || typ === 'interactive' || typ === 'button') return t;\n  const art = { image: 'Bild', audio: 'Sprachnachricht', video: 'Video', document: 'Dokument', sticker: 'Sticker', location: 'Standort', contacts: 'Kontakt', reaction: 'Reaktion' }[typ] || 'Nachricht';\n  return '[' + art + (t ? ': ' + t : ' ohne Text') + ']';\n}\n\n/**\n * Weg bestimmen: still | befehl | team | kunde\n * e = { nachricht, eingang, konv, team, testmodus, testNummern, verlauf }\n */\nfunction wegBestimmen(e) {\n  const n = e.nachricht || {};\n  const konv = e.konv || {};\n  const team = e.team && e.team.mitglied_id ? e.team : null;\n  const wa = String(n.kontakt_extern || '').replace(/\\D/g, '');\n  const text = String(n.text || '').trim();\n  const basis = { konversation_id: n.konversation_id, wa, nachricht_id: n.nachricht_id, team };\n  if (!wa || !n.konversation_id) return { ...basis, weg: 'still', grund: 'unvollständig' };\n  // Neuere Kundennachricht vorhanden? Dann antwortet der spätere Lauf auf alles zusammen.\n  const neuer = (e.verlauf || []).some(v => v.richtung === 'ein' && v.nachricht_id !== n.nachricht_id && String(v.zeit) > String(n.zeit));\n  if (neuer) return { ...basis, weg: 'still', grund: 'neuere Nachricht folgt' };\n  if (team && /^\\/(kunde|team)$/i.test(text)) return { ...basis, weg: 'befehl', ansicht: text.toLowerCase() === '/kunde' ? 'kunde' : null };\n  if (konv.modus === 'mensch') return { ...basis, weg: 'still', grund: 'Mensch hat übernommen' };\n  if (team && konv.ansicht !== 'kunde') return { ...basis, weg: 'team' };\n  if (e.testmodus && !(e.testNummern || []).includes(wa)) return { ...basis, weg: 'still', grund: 'Testmodus' };\n  return { ...basis, weg: 'kunde' };\n}\n\n/** Verlauf aus kom_nachrichten (neueste zuerst) → Chat-Nachrichten in zeitlicher Reihenfolge. */\nfunction verlaufAlsChat(verlauf, ohneId, max) {\n  return (verlauf || []).filter(v => v && v.nachricht_id !== ohneId).slice(0, max || 20).reverse()\n    .map(v => ({ role: v.richtung === 'ein' ? 'user' : 'assistant', content: v.richtung === 'ein' ? textFuerKi(v) : String(v.text || '') }))\n    .filter(m => m.content);\n}\n\n/** Anfrage an das Sprachmodell für den Kunden-Bot. */\nfunction kundenAnfrage(promptVorlage, wissen, e) {\n  const n = e.nachricht || {};\n  const erst = !!(e.eingang && e.eingang.erstkontakt);\n  const ersetzen = {\n    kanal: 'WhatsApp',\n    kontakt_name: n.kontakt_name || 'unbekannt',\n    erstkontakt: erst\n      ? 'ja – das ist die erste Nachricht des Leads, es gab noch keine Begrüßung. Befolge die Regel „Erste Antwort“ und setz als eigene letzte Zeile: „' + DATENSCHUTZ_ZEILE + '“.'\n      : 'nein',\n    marke: (e.konv && e.konv.marke) || 'offen',\n    verlauf: '(siehe Chatverlauf)'\n  };\n  const system = String(promptVorlage).replace(/\\{\\{(\\w+)\\}\\}/g, (m, k) => (k in ersetzen ? ersetzen[k] : m)) + '\\n\\n---\\n\\n# WISSENSBASIS\\n\\n' + wissen;\n  const messages = [{ role: 'system', content: system }].concat(verlaufAlsChat(e.verlauf, null, 20));\n  if (!messages.some(m => m.role === 'user')) messages.push({ role: 'user', content: textFuerKi(n) || 'Hallo' });\n  return { model: 'gpt-5-mini', reasoning_effort: 'low', max_completion_tokens: 2500, response_format: { type: 'json_object' }, messages };\n}\n\nconst PREIS = /(\\d[\\d.,]*\\s?(€|eur\\b|euro))|((€|eur)\\s?\\d)/i;\n\n/** Antwort des Modells prüfen und in eine sendefertige Nachricht verwandeln. erst = erste Antwort (Fall B): Datenschutz-Zeile absichern. */\nfunction antwortPruefen(roh, wa, erst) {\n  let a = {};\n  try {\n    const c = roh && roh.choices && roh.choices[0] && roh.choices[0].message ? roh.choices[0].message.content : '';\n    const m = String(c || '').match(/\\{[\\s\\S]*\\}/);\n    a = m ? JSON.parse(m[0]) : {};\n  } catch (err) { a = {}; }\n  let text = String(a.antwort || '').trim().replace(/\\*\\*(.+?)\\*\\*/g, '*$1*').replace(/^#+\\s*/gm, '');\n  const meta = {\n    marke: ['momentum', 'hermetik', 'offen'].includes(a.marke) ? a.marke : 'offen',\n    absicht: String(a.absicht || ''), phase: String(a.phase || ''),\n    termin_link: String(a.termin_link || 'keiner'),\n    uebergabe: a.uebergabe === true, uebergabe_grund: String(a.uebergabe_grund || '').slice(0, 200),\n    zusammenfassung: String(a.zusammenfassung || '').slice(0, 500),\n    qualifizierung: a.qualifizierung && typeof a.qualifizierung === 'object' ? a.qualifizierung : {},\n    pruefung: 'ok'\n  };\n  if (!text) {\n    text = 'Danke für deine Nachricht! Ich gebe sie an unser Team weiter, es meldet sich innerhalb eines Werktags bei dir. Schneller geht es über einen Termin: ' + BUCHUNG_KARSTEN;\n    meta.uebergabe = true; meta.uebergabe_grund = 'KI-Antwort leer oder ungültig'; meta.pruefung = 'ersatz';\n  } else if (PREIS.test(text)) {\n    text = 'Konkrete Kosten und den Eigenanteil kann ich hier nicht nennen, die hängen von deinem Betrieb und der Förderung ab. Karsten prüft das im Fördervorgespräch genau: ' + BUCHUNG_KARSTEN;\n    meta.pruefung = 'preis_entfernt';\n  }\n  if (text.length > 1500) text = text.slice(0, 1500).replace(/\\s+\\S*$/, '') + ' …';\n  if (erst) text = mitDatenschutz(text);\n  let buttons = Array.isArray(a.buttons) ? a.buttons.map(b => String(b || '').trim()).filter(b => b && b.length <= 20).slice(0, 3) : [];\n  if (text.length > 1024) buttons = [];\n  return { art: 'kunde', to: wa, text, buttons, meta };\n}\n\n/** Feste erste Antwort: Fall A (nur Gruß, mit zwei Knöpfen) oder Fall C (neutraler Webseiten-Text, gleiche Knöpfe). */\nfunction begruessung(wa, fall) {\n  const c = fall === 'C';\n  return { art: 'kunde', to: wa, text: c ? BEGRUESSUNG_WEBSEITE : BEGRUESSUNG, buttons: KNOEPFE.slice(), meta: { marke: 'offen', phase: 'einstieg', zusammenfassung: '', uebergabe: false, pruefung: c ? 'begruessung_webseite' : 'begruessung' } };\n}\n\n/** Cloud-API-Nachricht bauen (Text oder Antwort-Buttons). */\nfunction waNachricht(p) {\n  const basis = { messaging_product: 'whatsapp', recipient_type: 'individual', to: String(p.to) };\n  if (p.buttons && p.buttons.length) {\n    return { ...basis, type: 'interactive', interactive: { type: 'button', body: { text: String(p.text).slice(0, 1024) },\n      action: { buttons: p.buttons.map((t, i) => ({ type: 'reply', reply: { id: 'b' + (i + 1) + '_' + t.toLowerCase().replace(/[^a-z0-9äöüß]+/g, '_').slice(0, 40), title: t } })) } } };\n  }\n  return { ...basis, type: 'text', text: { preview_url: true, body: String(p.text).slice(0, 4096) } };\n}\n\n/** Ergebnis der Cloud API auswerten. */\nfunction versandAuswerten(r) {\n  const code = Number(r && r.statusCode || 0);\n  const b = (r && r.body) || {};\n  const id = b.messages && b.messages[0] && b.messages[0].id;\n  if (code >= 200 && code < 300 && id) return { ok: true, nachricht_id: String(id), fehler: null };\n  const f = b.error || {};\n  return { ok: false, nachricht_id: 'fehler-' + Date.now(), fehler: { code: f.code || code, titel: f.message || 'Versand fehlgeschlagen', details: (f.error_data && f.error_data.details) || null } };\n}\n";
// Übergabe an die Vertriebs-Pipeline aus kommunikation/lib/crm.js (getestet)
const CRM = "// Kommunikation: Übergabe eines WhatsApp-Gesprächs an die Vertriebs-Pipeline (Twenty CRM).\n// Läuft im n8n-Code-Knoten (eingebettet von kommunikation/n8n/bauen-antwort.mjs) und in Node (Tests).\n// Kein Netzwerk, kein require, keine KI. Die HTTP-Knoten im Workflow schicken nur, was diese Funktionen bauen.\n// Datenschutz: Ins CRM gehen Name, Telefonnummer, Marke und die Zusammenfassung des Bots, nie der Chatverlauf.\n// Namen sind bewusst mit „crm“ vorangestellt, damit sie im Code-Knoten nicht mit dessen eigenen Variablen kollidieren.\n\nconst CRM_PRAEFIX = 'WhatsApp: ';\nconst CRM_TEST_PRAEFIX = 'TEST ';\n// Stufe „(Noch) kein Termin gebucht“, erste Spalte der Pipeline. So legen auch das Portal („Neue Verkaufschance“)\n// und der Leadmagnet neue Kontakte an. ERSTKONTAKT heißt „Fokus Erstkontakt“ und ist schon Karstens Arbeitsschritt.\nconst CRM_STUFE_NEU = 'NEW';\nconst CRM_NOTIZ_TITEL = 'WhatsApp-Bot: Zusammenfassung';\nconst CRM_LAENDER = { '49': 'DE', '43': 'AT', '41': 'CH' };\nconst CRM_MARKEN = { momentum: 'Momentum KI Akademie', hermetik: 'Hermetik Marketing', offen: 'noch offen' };\n\nconst crmZiffern = v => String(v || '').replace(/\\D/g, '');\nconst crmEsc = s => String(s || '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n\n/** wa_id (Ziffern mit Ländervorwahl) → Telefonfeld im Format von Twenty, wie es das Portal anlegt. */\nfunction crmTelefon(waId) {\n  const z = crmZiffern(waId);\n  if (z.length < 8 || z.length > 15) return null;\n  for (const cc of Object.keys(CRM_LAENDER)) {\n    if (z.startsWith(cc)) return { primaryPhoneNumber: z.slice(cc.length), primaryPhoneCallingCode: '+' + cc, primaryPhoneCountryCode: CRM_LAENDER[cc] };\n  }\n  return { primaryPhoneNumber: z }; // andere Länder: wie das Portal, ganze Nummer ohne „+“\n}\n\n/** Schreibweisen, unter denen dieselbe Nummer in Twenty stehen kann. */\nfunction crmTelefonVarianten(waId) {\n  const z = crmZiffern(waId);\n  const t = crmTelefon(z);\n  if (!t) return [];\n  const v = [t.primaryPhoneNumber, z, '+' + z];\n  if (t.primaryPhoneCallingCode) v.push('0' + t.primaryPhoneNumber);\n  return [...new Set(v)];\n}\n\n/** REST-Pfad: Personen mit dieser Telefonnummer suchen. */\nfunction crmPersonSuchPfad(waId) {\n  const f = 'or(' + crmTelefonVarianten(waId).map(v => 'phones.primaryPhoneNumber[eq]:\"' + v + '\"').join(',') + ')';\n  return 'people?limit=10&filter=' + encodeURIComponent(f);\n}\n\n/** Gehört die Twenty-Person zu dieser WhatsApp-Nummer? Vergleicht vollständige Nummern, nicht Teilstrings. */\nfunction crmPersonPasst(person, waId) {\n  const z = crmZiffern(waId);\n  const ph = (person && person.phones) || {};\n  const nr = crmZiffern(ph.primaryPhoneNumber);\n  if (!z || !nr) return false;\n  const cc = crmZiffern(ph.primaryPhoneCallingCode);\n  const kandidaten = [nr];\n  if (cc) kandidaten.push(cc + nr.replace(/^0+/, ''));\n  else if (/^0[1-9]/.test(nr)) kandidaten.push('49' + nr.slice(1));\n  return kandidaten.includes(z);\n}\n\n/** ID eines eben angelegten oder gelesenen Datensatzes aus einer Twenty-Antwort ({ data: { createPerson: { id } } } u. ä.). */\nfunction crmNeueId(antwort) {\n  const d = antwort && antwort.data;\n  if (!d || typeof d !== 'object') return '';\n  const v = Object.values(d)[0];\n  return (v && !Array.isArray(v) && v.id) || '';\n}\n\n/** Person für Twenty: Profilname (sonst „WhatsApp-Kontakt“) und Telefonnummer. */\nfunction crmPersonBody(kontaktName, waId) {\n  const n = String(kontaktName || '').replace(/[\\u0000-\\u001F]/g, ' ').replace(/\\s+/g, ' ').trim().slice(0, 120) || 'WhatsApp-Kontakt';\n  const teile = n.split(' ');\n  const b = { name: { firstName: teile[0].slice(0, 60), lastName: teile.slice(1).join(' ').slice(0, 80) } };\n  const tel = crmTelefon(waId);\n  if (tel) b.phones = tel;\n  return b;\n}\n\n/**\n * Nach der Personensuche: vorhandene Person wiederverwenden (bekannte ID zuerst), sonst neu anlegen.\n * Vorhandene Person → kein Twenty-Aufruf („Person neu?“ springt direkt zu „Person übernehmen“), nichts wird überschrieben.\n */\nfunction crmPersonSchritt(antwort, waId, kontaktName, bekannteId) {\n  const L = ((antwort && antwort.data && antwort.data.people) || []).filter(p => p && p.id && !p.deletedAt && crmPersonPasst(p, waId));\n  const treffer = L.find(p => p.id === bekannteId) || L[0];\n  if (treffer) return { person_neu: false, person_id: treffer.id };\n  return { person_neu: true, person_id: '', methode: 'POST', pfad: 'people', body: crmPersonBody(kontaktName, waId) };\n}\n\n/** Personen-ID übernehmen (vorhanden oder eben angelegt) und die Chancen dieser Person abfragen. */\nfunction crmPersonUebernehmen(antwort, vorhandeneId) {\n  const id = vorhandeneId || crmNeueId(antwort);\n  if (!id) throw new Error('Twenty hat keine Personen-ID geliefert.');\n  return { person_id: id, pfad: 'opportunities?limit=20&filter=' + encodeURIComponent('pointOfContactId[eq]:' + id) };\n}\n\n/** Name der Chance: „WhatsApp: <Name>“ (bei Tests „TEST WhatsApp: …“). */\nfunction crmChanceName(kontaktName, test) {\n  const n = String(kontaktName || '').replace(/\\s+/g, ' ').trim().slice(0, 100) || 'WhatsApp-Kontakt';\n  return (test ? CRM_TEST_PRAEFIX : '') + CRM_PRAEFIX + n;\n}\n\n/** Neue Chance: Stufe NEW, verknüpft mit der Person, Eingang und letzter Kontakt = jetzt. */\nfunction crmChanceBody(e) {\n  return { name: crmChanceName(e.name, e.test), stage: CRM_STUFE_NEU, pointOfContactId: e.person_id, letzterKontakt: e.jetzt, eingangAm: e.jetzt };\n}\n\n/** Nach der Chancensuche: Hat die Person schon eine WhatsApp-Chance (z. B. nach einem abgebrochenen Lauf)? Dann fortschreiben. */\nfunction crmChanceSchritt(antwort, e) {\n  const L = ((antwort && antwort.data && antwort.data.opportunities) || []).filter(o => o && o.id && !o.deletedAt);\n  const da = L.find(o => String(o.name || '').startsWith(CRM_PRAEFIX) || String(o.name || '').startsWith(CRM_TEST_PRAEFIX + CRM_PRAEFIX));\n  if (da) return { chance_neu: false, chance_id: da.id, methode: 'PATCH', pfad: 'opportunities/' + da.id, body: { letzterKontakt: e.jetzt } };\n  return { chance_neu: true, chance_id: '', methode: 'POST', pfad: 'opportunities', body: crmChanceBody(e) };\n}\n\n/** REST-Pfad: Notizen einer Chance (wie im Portal, Aktion „details“). */\nfunction crmNotizenPfad(chanceId) {\n  return 'noteTargets?limit=60&depth=1&filter=targetOpportunityId[eq]:' + chanceId;\n}\n\n/** Wiedergefundene Chance: vorhandene Bot-Notiz suchen, statt eine zweite anzulegen. */\nfunction crmNotizFinden(antwort) {\n  const L = ((antwort && antwort.data && antwort.data.noteTargets) || []).map(t => t && t.note).filter(n => n && n.id && !n.deletedAt && n.title === CRM_NOTIZ_TITEL);\n  return L.length ? L[0].id : null;\n}\n\n/** Notiz mit der Zusammenfassung des Bots (Markdown). Kein Chatverlauf. */\nfunction crmNotizBody(e) {\n  const zeit = new Date(e.jetzt || Date.now()).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short' });\n  const z = String(e.zusammenfassung || '').trim().slice(0, 1000);\n  const zeilen = [\n    '**Quelle:** WhatsApp-Bot',\n    '**Marke:** ' + (CRM_MARKEN[e.marke] || CRM_MARKEN.offen),\n    '**Stand:** ' + zeit\n  ];\n  if (e.uebergabe) zeilen.push('**Mensch gewünscht:** ' + (String(e.uebergabe_grund || '').slice(0, 200) || 'ja'));\n  const md = zeilen.join('  \\n') + '\\n\\n' + (z || '_Noch keine Zusammenfassung. Der Bot hat bisher nur begrüßt._') +\n    '\\n\\n_Nur die Zusammenfassung des Bots, kein Chatverlauf. Den Verlauf siehst du im Portal unter „WhatsApp-Inbox“._';\n  return { title: CRM_NOTIZ_TITEL, bodyV2: { markdown: md } };\n}\n\n/**\n * Entscheidung: nichts | anlegen | fortschreiben. Deterministisch, keine KI.\n * e = { weg, team, testmodus, crmTest, art, versandOk, uebergabe, konv }\n */\nfunction crmEntscheidung(e) {\n  const konv = e.konv || {};\n  if (e.weg !== 'kunde' || e.art !== 'kunde') return { aktion: 'nichts', grund: 'kein Kundengespräch', test: false };\n  const istTeam = !!(e.team && e.team.mitglied_id);\n  if ((istTeam || e.testmodus) && !e.crmTest) return { aktion: 'nichts', grund: istTeam ? 'Teammitglied' : 'Testmodus', test: false };\n  const test = istTeam || !!e.testmodus;\n  if (!e.versandOk && !e.uebergabe) return { aktion: 'nichts', grund: 'Bot hat noch nicht geantwortet', test };\n  if (konv.twenty_chance_id) return { aktion: 'fortschreiben', grund: 'Chance vorhanden', test };\n  return { aktion: 'anlegen', grund: konv.crm_fehler ? 'neuer Versuch nach Fehler' : 'erste Antwort', test };\n}\n\n/**\n * Alles, was die Nachbereitung für die CRM-Übergabe braucht.\n * e = { W (Weg bestimmen), E (Einstellungen), V (Versand auswerten), p (Antwort), jetzt }\n */\nfunction crmPlan(e) {\n  const W = e.W || {}, E = e.E || {}, V = e.V || {}, p = e.p || {};\n  const m = p.meta || {};\n  const konv = W.konv || {};\n  const jetzt = e.jetzt || new Date().toISOString();\n  const d = crmEntscheidung({ weg: W.weg, team: W.team, testmodus: E.testmodus === true, crmTest: E.crm_test === true, art: p.art, versandOk: V.ok === true, uebergabe: m.uebergabe === true, konv });\n  const plan = { aktion: d.aktion, grund: d.grund, test: d.test };\n  if (d.aktion === 'nichts') return plan;\n  const marke = m.marke && m.marke !== 'offen' ? m.marke : (konv.marke || 'offen');\n  const zusammenfassung = String(m.zusammenfassung || konv.zusammenfassung || '');\n  const name = String((W.nachricht && W.nachricht.kontakt_name) || konv.kontakt_name || '');\n  const notiz = crmNotizBody({ zusammenfassung, marke, uebergabe: m.uebergabe === true, uebergabe_grund: m.uebergabe_grund, jetzt });\n  Object.assign(plan, { wa: W.wa, name, marke, zusammenfassung, jetzt, notiz_body: notiz });\n  if (d.aktion === 'anlegen') {\n    plan.person_pfad = crmPersonSuchPfad(W.wa);\n    plan.person_id = konv.twenty_person_id || '';\n  } else {\n    plan.chance_id = konv.twenty_chance_id;\n    plan.chance_pfad = 'opportunities/' + konv.twenty_chance_id;\n    plan.chance_body = { letzterKontakt: jetzt };\n    const neu = !!m.zusammenfassung && m.zusammenfassung !== konv.zusammenfassung;\n    plan.notiz_neu = !!konv.crm_notiz_id && (neu || m.uebergabe === true);\n    plan.notiz_pfad = konv.crm_notiz_id ? 'notes/' + konv.crm_notiz_id : '';\n  }\n  return plan;\n}\n\n/** Abschluss nach erfolgreichem Anlegen: Werte für kom_konversationen und Telegram-Text. */\nfunction crmErgebnis(e) {\n  const patch = { twenty_person_id: e.person_id, twenty_chance_id: e.chance_id, crm_notiz_id: e.notiz_id || null, crm_uebergeben_am: e.jetzt, crm_fehler: null };\n  const telegram = e.chance_neu ? crmTelegramNeu(e.plan || {}) : '';\n  return { patch, neu: !!e.chance_neu, telegram };\n}\n\n/** Telegram an Timo bei jeder neu angelegten Chance. Telefonnummer wie in der Meldung „Mensch gewünscht“. */\nfunction crmTelegramNeu(plan) {\n  return '📇 <b>Neuer WhatsApp-Kontakt in der Pipeline</b>' + (plan.test ? ' (TEST)' : '') + '\\n' +\n    crmEsc(plan.name || 'WhatsApp-Kontakt') + ' · +' + crmEsc(plan.wa) + '\\n' +\n    'Marke: ' + crmEsc(CRM_MARKEN[plan.marke] || CRM_MARKEN.offen) + '\\n' +\n    'Kurz: ' + crmEsc(String(plan.zusammenfassung || 'noch keine Zusammenfassung').slice(0, 300)) + '\\n' +\n    'Stufe „(Noch) kein Termin gebucht“, im Portal unter Vertrieb.';\n}\n\n/** Fehler vermerken: Die Konversation bekommt crm_fehler, eine schon angelegte Person wird gemerkt (keine Dublette beim nächsten Versuch). */\nfunction crmFehlerPatch(e) {\n  const f = e.fehler;\n  const text = typeof f === 'string' ? f : (f && (f.message || f.description)) ? String(f.message || f.description) : JSON.stringify(f || 'unbekannt');\n  const patch = { crm_fehler: (new Date(e.jetzt || Date.now()).toISOString() + ' ' + (e.aktion || '') + ': ' + text).slice(0, 500) };\n  if (e.person_id) patch.twenty_person_id = e.person_id;\n  return { patch };\n}\n";

