export default workflow('kom-wa-antwort', 'KOM: WhatsApp Antwort (Workflow B)')
  .add(start).to(einstellungen).to(sammeln).to(teamKontakt).to(konvLaden).to(verlaufLaden).to(weg)
  .to(wegSwitch
    .onCase(0, wissenLaden.to(kundeVorb).to(nurGruss.onTrue(begruessung.to(modusPruefen)).onFalse(kiFragen.to(pruefen).to(modusPruefen))))
    .onCase(1, teamFrage.to(teamToken).to(teamAssistent).to(teamAntwort).to(modusPruefen))
    .onCase(2, ansichtSetzen.to(befehlAntwort).to(modusPruefen)))
  .add(modusPruefen).to(sendenVorb).to(senden).to(auswerten).to(speichern).to(nachbereitung).to(konvAkt)
  .to(uebergabe.onTrue(pausieren))
  .add(konvAkt).to(telegramNoetig.onTrue(telegram))
  .add(konvAkt).to(crmWeiche.onCase(0, crmPersonSuchen).onCase(1, crmChanceFort))
  .add(crmPersonSuchen.output(0).to(crmPersonWaehlen))
  .add(crmPersonSuchen.output(1).to(crmFehler))
  .add(crmPersonWaehlen.output(0).to(crmPersonNeu))
  .add(crmPersonWaehlen.output(1).to(crmFehler))
  .add(crmPersonSpeichern.output(0).to(crmPersonUebernehmen))
  .add(crmPersonSpeichern.output(1).to(crmFehler))
  .add(crmPersonUebernehmen.output(0).to(crmChancenLaden))
  .add(crmPersonUebernehmen.output(1).to(crmFehler))
  .add(crmChancenLaden.output(0).to(crmChanceWaehlen))
  .add(crmChancenLaden.output(1).to(crmFehler))
  .add(crmChanceWaehlen.output(0).to(crmChanceSpeichern))
  .add(crmChanceWaehlen.output(1).to(crmFehler))
  .add(crmChanceSpeichern.output(0).to(crmNotizBauen))
  .add(crmChanceSpeichern.output(1).to(crmFehler))
  .add(crmNotizBauen.output(0).to(crmChanceNeu))
  .add(crmNotizBauen.output(1).to(crmFehler))
  .add(crmNotizAnlegen.output(0).to(crmNotizVerknuepfen))
  .add(crmNotizAnlegen.output(1).to(crmFehler))
  .add(crmNotizVerknuepfen.output(0).to(crmErgebnisKnoten))
  .add(crmNotizVerknuepfen.output(1).to(crmFehler))
  .add(crmNotizenLaden.output(0).to(crmErgebnisKnoten))
  .add(crmNotizenLaden.output(1).to(crmFehler))
  .add(crmErgebnisKnoten.output(0).to(crmStandSpeichern))
  .add(crmErgebnisKnoten.output(1).to(crmFehler))
  .add(crmChanceFort.output(0).to(crmNotizNeu))
  .add(crmChanceFort.output(1).to(crmFehler))
  .add(crmPersonNeu.onTrue(crmPersonSpeichern).onFalse(crmPersonUebernehmen))
  .add(crmChanceNeu.onTrue(crmNotizAnlegen).onFalse(crmNotizenLaden))
  .add(crmNotizFort.output(1).to(crmFehler))
  .add(crmStandSpeichern.output(0).to(crmNeuPruefen))
  .add(crmNeuPruefen.onTrue(crmTelegram))
  .add(crmNotizNeu.onTrue(crmNotizFort))
  .add(crmFehler.output(0).to(crmFehlerSpeichern));
